-- +goose Up
-- Private share identities are generated by this database, never imported from
-- account/profile JSON. Existing link IDs do not acquire original witnesses.
ALTER TABLE accounts ADD COLUMN share_incarnation UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid();
ALTER TABLE users ADD COLUMN share_incarnation UUID NOT NULL DEFAULT pg_catalog.gen_random_uuid();

-- +goose StatementBegin
CREATE FUNCTION rotate_share_account_incarnation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  NEW.share_incarnation:=pg_catalog.gen_random_uuid();
 ELSIF (NEW.id,NEW.is_master,NEW.password_hash,NEW.expires_at)
       IS DISTINCT FROM (OLD.id,OLD.is_master,OLD.password_hash,OLD.expires_at)
       OR NEW.share_incarnation IS DISTINCT FROM OLD.share_incarnation THEN
  NEW.share_incarnation:=pg_catalog.gen_random_uuid();
 ELSE
  NEW.share_incarnation:=OLD.share_incarnation;
 END IF;
 RETURN NEW;
END;
$$;
-- +goose StatementEnd
CREATE TRIGGER accounts_share_incarnation BEFORE INSERT OR UPDATE ON accounts
 FOR EACH ROW EXECUTE FUNCTION rotate_share_account_incarnation();

-- +goose StatementBegin
CREATE FUNCTION rotate_share_profile_incarnation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF TG_OP='INSERT' THEN
  NEW.share_incarnation:=pg_catalog.gen_random_uuid();
 ELSIF (NEW.id,NEW.account_id,NEW.allow_share_links,NEW.pin_hash,NEW.pin_length,
        NEW.is_kids_profile,NEW.kids_mode,NEW.kids_max_rating,
        NEW.kids_max_movie_rating,NEW.kids_max_tv_rating,NEW.kids_allowed_lists)
       IS DISTINCT FROM
       (OLD.id,OLD.account_id,OLD.allow_share_links,OLD.pin_hash,OLD.pin_length,
        OLD.is_kids_profile,OLD.kids_mode,OLD.kids_max_rating,
        OLD.kids_max_movie_rating,OLD.kids_max_tv_rating,OLD.kids_allowed_lists)
       OR NEW.share_incarnation IS DISTINCT FROM OLD.share_incarnation THEN
  NEW.share_incarnation:=pg_catalog.gen_random_uuid();
 ELSE
  NEW.share_incarnation:=OLD.share_incarnation;
 END IF;
 RETURN NEW;
END;
$$;
-- +goose StatementEnd
CREATE TRIGGER users_share_incarnation BEFORE INSERT OR UPDATE ON users
 FOR EACH ROW EXECUTE FUNCTION rotate_share_profile_incarnation();

ALTER TABLE share_links
 ADD COLUMN delegation_version SMALLINT,
 ADD COLUMN creator_incarnation UUID,
 ADD COLUMN source_owner_incarnation UUID,
 ADD COLUMN source_profile_incarnation UUID,
 ADD CONSTRAINT share_link_delegation_shape CHECK (
  (delegation_version IS NULL AND creator_incarnation IS NULL
   AND source_owner_incarnation IS NULL AND source_profile_incarnation IS NULL)
  OR (delegation_version IS NOT NULL AND delegation_version=1
   AND provenance_version=1 AND source_profile_id IS NOT NULL AND source_account_id IS NOT NULL
   AND creator_incarnation IS NOT NULL AND creator_incarnation<>'00000000-0000-0000-0000-000000000000'::uuid
   AND source_owner_incarnation IS NOT NULL AND source_owner_incarnation<>'00000000-0000-0000-0000-000000000000'::uuid
   AND source_profile_incarnation IS NOT NULL AND source_profile_incarnation<>'00000000-0000-0000-0000-000000000000'::uuid)
 );

ALTER TABLE sessions ADD COLUMN share_binding_id UUID
 CHECK (share_binding_id IS NULL OR share_binding_id<>'00000000-0000-0000-0000-000000000000'::uuid);
ALTER TABLE sessions ADD CONSTRAINT sessions_share_binding_identity UNIQUE(token,share_binding_id);

-- Neither these witnesses nor the private nonce are backup/import fields.
-- A restored ordinary session/link cannot recreate an original delegation.
CREATE TABLE share_playback_bindings (
 session_token TEXT PRIMARY KEY CHECK (octet_length(session_token)=43 AND session_token ~ '^[A-Za-z0-9_-]{43}$'),
 binding_id UUID NOT NULL CHECK (binding_id<>'00000000-0000-0000-0000-000000000000'::uuid),
 share_token TEXT NOT NULL REFERENCES share_links(token) ON DELETE CASCADE
 CHECK (octet_length(share_token)=43 AND share_token ~ '^[A-Za-z0-9_-]{43}$'),
 creator_id TEXT NOT NULL CHECK (octet_length(creator_id) BETWEEN 1 AND 256 AND creator_id=btrim(creator_id)),
 creator_incarnation UUID NOT NULL CHECK (creator_incarnation<>'00000000-0000-0000-0000-000000000000'::uuid),
 source_account_id TEXT NOT NULL CHECK (octet_length(source_account_id) BETWEEN 1 AND 256 AND source_account_id=btrim(source_account_id)),
 source_owner_incarnation UUID NOT NULL CHECK (source_owner_incarnation<>'00000000-0000-0000-0000-000000000000'::uuid),
 source_profile_id TEXT NOT NULL CHECK (octet_length(source_profile_id) BETWEEN 1 AND 256 AND source_profile_id=btrim(source_profile_id)),
 source_profile_incarnation UUID NOT NULL CHECK (source_profile_incarnation<>'00000000-0000-0000-0000-000000000000'::uuid),
 resource TEXT NOT NULL CHECK (octet_length(resource) BETWEEN 1 AND 1048576 AND resource=btrim(resource)),
 created_at TIMESTAMPTZ NOT NULL,
 expires_at TIMESTAMPTZ NOT NULL CHECK (expires_at>created_at AND expires_at<=created_at+INTERVAL '6 hours'),
 FOREIGN KEY (session_token,binding_id) REFERENCES sessions(token,share_binding_id) ON DELETE CASCADE
);

-- Deactivation is a durable revocation, even if re-enabled between checks.
-- Max-use accounting intentionally does not retire already-issued bindings.
-- +goose StatementBegin
CREATE FUNCTION revoke_inactive_share_playback() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.active AND NOT NEW.active THEN
  EXECUTE format('DELETE FROM %I.share_playback_bindings WHERE share_token=$1',TG_TABLE_SCHEMA) USING NEW.token;
 END IF;
 RETURN NEW;
END;
$$;
-- +goose StatementEnd
CREATE TRIGGER share_links_playback_revocation AFTER UPDATE OF active ON share_links
 FOR EACH ROW EXECUTE FUNCTION revoke_inactive_share_playback();

-- +goose Down
DROP TRIGGER share_links_playback_revocation ON share_links;
DROP FUNCTION revoke_inactive_share_playback();
DROP TABLE share_playback_bindings;
ALTER TABLE sessions DROP CONSTRAINT sessions_share_binding_identity;
ALTER TABLE sessions DROP COLUMN share_binding_id;
ALTER TABLE share_links DROP CONSTRAINT share_link_delegation_shape;
ALTER TABLE share_links DROP COLUMN delegation_version,
 DROP COLUMN creator_incarnation,DROP COLUMN source_owner_incarnation,DROP COLUMN source_profile_incarnation;
DROP TRIGGER users_share_incarnation ON users;
DROP TRIGGER accounts_share_incarnation ON accounts;
